PUNCT = ".,;:!?\"'()"


def tokenize(text):
    """Split text into raw word tokens.

    Words are separated by any run of whitespace (spaces, tabs,
    newlines, multiples in a row).
    """
    return text.split()


def clean(token):
    """Strip surrounding punctuation from a token and lowercase it.

    Comparison is case-insensitive, so the cleaned form is lowercased;
    a token that is only punctuation cleans to the empty string.
    """
    return token.strip(PUNCT).lower()

"""Text summary statistics."""

from .helpers import clean, tokenize


def summarize(text):
    """Return word count, unique word count and average word length."""
    tokens = tokenize(text)
    cleaned = [clean(t) for t in tokens]
    words = [c for c in cleaned if c]
    if not words:
        return {"words": 0, "unique": 0, "avg_len": 0.0}
    unique = len(set(words))
    avg_len = round(sum(len(w) for w in words) / len(words), 2)
    return {"words": len(words), "unique": unique, "avg_len": avg_len}

